// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IZKFirmaDigitalVote {
    struct Proposal {
        string description;
        uint256 voteCount;
    }

    event Voted(address indexed _from, uint256 indexed _propositionIndex);

    function voteForProposal(
        uint256 proposalIndex,
        uint nullifierSeed,
        uint nullifier,
        uint signal,
        uint[1] calldata revealArray,
        uint[8] calldata groth16Proof
    ) external;

    function getProposalCount() external view returns (uint256);
    function getProposal(uint256 proposalIndex) external view returns (string memory, uint256);
    function getTotalVotes() external view returns (uint256);
    function checkVoted(uint256 _nullifier) external view returns (bool);
}

/**
 * @title TestZKVote
 * @dev Minimal testing contract implementing the small interface expected by the frontend.
 *      For simplicity this contract does NOT verify ZK proofs — it trusts the caller.
 *      This is for local / Sepolia testing only. Do NOT use in production.
 */
contract TestZKVote is IZKFirmaDigitalVote {
    Proposal[] private _proposals;
    mapping(uint256 => bool) private _nullifiers; // simple global nullifier map for test

    // Simple vote params struct
    string public votingQuestion;
    uint256 public identityCreationTimestampUpperBound;
    uint256 public birthDateLowerbound;
    uint256 public expirationDateLowerBound;
    uint256 public identityCounterUpperBound;
    uint64 public voteScope;

    address public owner;

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor(string memory _question, string[] memory _initialProposals) {
        owner = msg.sender;
        votingQuestion = _question;
        for (uint256 i = 0; i < _initialProposals.length; i++) {
            _proposals.push(Proposal({ description: _initialProposals[i], voteCount: 0 }));
        }
        // sensible defaults for testing
        identityCreationTimestampUpperBound = block.timestamp + 365 days;
        birthDateLowerbound = 0;
        expirationDateLowerBound = block.timestamp + 365 days;
        identityCounterUpperBound = 0;
        voteScope = 1;
    }

    // Owner helpers
    function addProposal(string calldata description) external onlyOwner {
        _proposals.push(Proposal({ description: description, voteCount: 0 }));
    }

    function setVoteParams(
        string calldata _question,
        uint256 _identityCreationTimestampUpperBound,
        uint256 _birthDateLowerbound,
        uint256 _expirationDateLowerBound,
        uint256 _identityCounterUpperBound,
        uint64 _voteScope
    ) external onlyOwner {
        votingQuestion = _question;
        identityCreationTimestampUpperBound = _identityCreationTimestampUpperBound;
        birthDateLowerbound = _birthDateLowerbound;
        expirationDateLowerBound = _expirationDateLowerBound;
        identityCounterUpperBound = _identityCounterUpperBound;
        voteScope = _voteScope;
    }

    // --- IZKFirmaDigitalVote implementation ---
    function voteForProposal(
        uint256 proposalIndex,
        uint /* nullifierSeed */,
        uint nullifier,
        uint /* signal */,
        uint[1] calldata /* revealArray */,
        uint[8] calldata /* groth16Proof */
    ) external override {
        require(proposalIndex < _proposals.length, "Invalid proposal");
        require(!_nullifiers[nullifier], "Nullifier already used");

        _nullifiers[nullifier] = true;
        _proposals[proposalIndex].voteCount += 1;

        emit Voted(msg.sender, proposalIndex);
    }

    function getProposalCount() external view override returns (uint256) {
        return _proposals.length;
    }

    function getProposal(uint256 proposalIndex) external view override returns (string memory, uint256) {
        require(proposalIndex < _proposals.length, "Invalid proposal");
        Proposal memory p = _proposals[proposalIndex];
        return (p.description, p.voteCount);
    }

    function getTotalVotes() external view override returns (uint256) {
        uint256 total = 0;
        for (uint256 i = 0; i < _proposals.length; i++) total += _proposals[i].voteCount;
        return total;
    }

    function checkVoted(uint256 _nullifier) external view override returns (bool) {
        return _nullifiers[_nullifier];
    }

    // voteParams() expected by frontend
    function voteParams()
        external
        view
        returns (
            string memory _votingQuestion,
            uint256 _identityCreationTimestampUpperBound,
            uint256 _birthDateLowerbound,
            uint256 _expirationDateLowerBound,
            uint256 _identityCounterUpperBound,
            uint64 _voteScope
        )
    {
        return (
            votingQuestion,
            identityCreationTimestampUpperBound,
            birthDateLowerbound,
            expirationDateLowerBound,
            identityCounterUpperBound,
            voteScope
        );
    }
}

